#include <cstdlib>
#include <fstream>
#include <iostream>
#include <iterator>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

static string expected(const string& input) {
    istringstream in(input);
    int t; in >> t;
    string out;
    while (t--) {
        int n; in >> n;
        vector<long long> a(n);
        long long sum = 0;
        for (int i = 0; i < n; ++i) { in >> a[i]; sum += a[i]; }
        long long tot = 0; bool ok = false;
        for (int i = 0; i + 1 < n; ++i) {
            tot += a[i];
            if (tot * 2 == sum) { ok = true; break; }
        }
        out += ok ? "Yes\n" : "No\n";
    }
    return out;
}

static string show(const string& s) {
    string r;
    for (char c : s) {
        if (c == '\n') r += "\\n"; else r += c;
        if (r.size() > 120) { r += "..."; break; }
    }
    return r;
}

static bool check(const string& exe, const string& input, int id) {
    const string inFile = "l3a09p1_input.txt", outFile = "l3a09p1_output.txt";
    { ofstream out(inFile); out << input; }
    const string cmd = "\"" + exe + "\" < " + inFile + " > " + outFile + " 2>/dev/null";
    int code = system(cmd.c_str());
    ifstream fin(outFile);
    string actual((istreambuf_iterator<char>(fin)), istreambuf_iterator<char>());
    string want = expected(input);
    bool ok = code == 0 && actual == want;
    if (!ok) cout << "[FAIL] case " << id << ": expected=" << show(want)
                  << " actual=" << show(actual).substr(0, 120)
                  << ", process status=" << code << '\n';
    return ok;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    vector<string> tests = {
        "3\n3\n1 2 3\n4\n2 3 1 4\n5\n1 2 3 4 5\n",
        "1\n1\n5\n",
        "1\n2\n1 1\n",
        "1\n2\n1 2\n",
        "1\n2\n10000 10000\n",
        "1\n3\n10000 10000 10000\n",
        "1\n4\n2 3 1 4\n",
        "1\n5\n1 2 3 4 5\n",
        "1\n6\n1 2 3 3 2 1\n"
    };
    // 边界：n 取上限 10000，全 1（i=5000 处平衡）与奇数和（必不平衡）
    {
        string s = "1\n10000\n";
        for (int i = 0; i < 10000; ++i) s += "1 ";
        s += "\n";
        tests.push_back(s);
    }
    {
        string s = "1\n9999\n";
        for (int i = 0; i < 9999; ++i) s += "1 ";
        s += "\n";
        tests.push_back(s);
    }
    {
        string s = "1\n10000\n";
        for (int i = 0; i < 9999; ++i) s += "1 ";
        s += "10000\n";
        tests.push_back(s);
    }
    // 随机压测：t=100 组，n 与 a_i 贴近上限范围
    {
        unsigned seed = 202409u;
        string s = "100\n";
        for (int c = 0; c < 100; ++c) {
            int n = 1 + static_cast<int>(seed % 100u); seed = seed * 1664525u + 1013904223u;
            s += to_string(n) + "\n";
            for (int i = 0; i < n; ++i) {
                seed = seed * 1664525u + 1013904223u;
                s += to_string(1 + static_cast<int>(seed % 10000u));
                s += (i + 1 == n ? "\n" : " ");
            }
        }
        tests.push_back(s);
    }
    int pass = 0;
    for (size_t i = 0; i < tests.size(); ++i)
        if (check(argv[1], tests[i], static_cast<int>(i + 1))) ++pass;
    cout << "Results: " << pass << "/" << tests.size() << " passed\n";
    return pass == static_cast<int>(tests.size()) ? 0 : 1;
}

