#include <cstdlib>
#include <fstream>
#include <iostream>
#include <iterator>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

static bool pal(const string& s) {
    for (size_t i = 0, j = s.size() - 1; i < j; ++i, --j)
        if (s[i] != s[j]) return false;
    return true;
}

static string expected(const string& input) {
    istringstream in(input);
    int n; in >> n;
    string out;
    while (n--) {
        string s; in >> s;
        int m = static_cast<int>(s.size());
        bool ok = false;
        for (int j = 2; j <= m - 2; ++j) {
            if (pal(s.substr(0, j)) && pal(s.substr(j))) { ok = true; break; }
        }
        out += ok ? "Yes\n" : "No\n";
    }
    return out;
}

static string show(const string& s) {
    string r;
    for (char c : s) {
        if (c == '\n') r += "\\n"; else r += c;
        if (r.size() > 120) { r += "..."; break; }
    }
    return r;
}

static bool check(const string& exe, const string& input, int id) {
    const string inFile = "l3a09p2_input.txt", outFile = "l3a09p2_output.txt";
    { ofstream out(inFile); out << input; }
    const string cmd = "\"" + exe + "\" < " + inFile + " > " + outFile + " 2>/dev/null";
    int code = system(cmd.c_str());
    ifstream fin(outFile);
    string actual((istreambuf_iterator<char>(fin)), istreambuf_iterator<char>());
    string want = expected(input);
    bool ok = code == 0 && actual == want;
    if (!ok) cout << "[FAIL] case " << id << ": expected=" << show(want)
                  << " actual=" << show(actual).substr(0, 120)
                  << ", process status=" << code << '\n';
    return ok;
}

static string randPal(unsigned& seed, int len) {
    string h;
    for (int i = 0; i < (len + 1) / 2; ++i) {
        seed = seed * 1664525u + 1013904223u;
        h += static_cast<char>('a' + seed % 3u);
    }
    string r = h;
    for (int i = static_cast<int>(h.size()) - 1; i >= 0; --i) r += h[i];
    return r.substr(0, len);
}

int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    vector<string> tests = {
        "4\nabcd\naabb\naaac\nabcdd\n",
        "1\naa\n",
        "1\naaa\n",
        "1\naaaa\n",
        "1\nabba\n",
        "1\naabbaa\n",
        "1\nabbaabba\n",
        "1\naabaa\n",
        "1\nab\n",
        "1\n" + string(100, 'a') + "\n",
        "1\n" + string(50, 'a') + string(50, 'b') + "\n"
    };
    // 随机压测：纯随机串与“两个回文拼接”的正例混合，长度贴近上限
    unsigned seed = 202409u;
    for (int trial = 0; trial < 8; ++trial) {
        string s = "10\n";
        for (int i = 0; i < 10; ++i) {
            string cur;
            if (trial % 2 == 0) {
                int l1 = 2 + static_cast<int>(seed % 40u); seed = seed * 1664525u + 1013904223u;
                int l2 = 2 + static_cast<int>(seed % 40u); seed = seed * 1664525u + 1013904223u;
                cur = randPal(seed, l1) + randPal(seed, l2);
            } else {
                int len = 1 + static_cast<int>(seed % 100u); seed = seed * 1664525u + 1013904223u;
                for (int k = 0; k < len; ++k) {
                    seed = seed * 1664525u + 1013904223u;
                    cur += static_cast<char>('a' + seed % 4u);
                }
            }
            s += cur + "\n";
        }
        tests.push_back(s);
    }
    int pass = 0;
    for (size_t i = 0; i < tests.size(); ++i)
        if (check(argv[1], tests[i], static_cast<int>(i + 1))) ++pass;
    cout << "Results: " << pass << "/" << tests.size() << " passed\n";
    return pass == static_cast<int>(tests.size()) ? 0 : 1;
}
